const buffer = new ArrayBuffer(8)
const view = new Uint8Array(buffer)
view[0] = 42
const clone = structuredClone(buffer)
const cloneView = new Uint8Array(clone)
return {
  original: view[0],
  cloned: cloneView[0],
  sameBuffer: buffer === clone
}
